  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// --- ENUMS ---\nenum Role {\n  ADMIN\n  MEMBER\n}\n\nenum RecipeUnit {\n  GRAMS\n  KILOGRAMS\n  MILLILITERS\n  LITERS\n  TABLESPOONS\n  OUNCES\n  UNITS\n}\n\n// --- MODELOS ---\nmodel Family {\n  id         String   @id @default(uuid())\n  name       String\n  inviteCode String   @unique @default(uuid())\n  createdAt  DateTime @default(now())\n\n  users             User[]\n  shoppingItems     ShoppingItem[]\n  tasks             Task[]\n  ideasPlans        IdeaPlan[]\n  recipes           Recipe[]\n  incomes           MonthlyIncome[]\n  expenseCategories ExpenseCategory[]\n  expenses          Expense[]\n  calendarEvents    CalendarEvent[]\n\n  @@map(\"families\")\n}\n\nmodel User {\n  id                        String    @id @default(uuid())\n  email                     String    @unique\n  passwordHash              String\n  name                      String\n  role                      Role      @default(MEMBER)\n  createdAt                 DateTime  @default(now())\n  emailVerified             Boolean   @default(true)\n  verificationCodeHash      String?\n  verificationCodeExpiresAt DateTime?\n\n  familyId      String\n  family        Family          @relation(fields: [familyId], references: [id])\n  incomes       MonthlyIncome[]\n  createdEvents CalendarEvent[]\n\n  @@map(\"users\")\n}\n\nmodel ShoppingItem {\n  id        String   @id @default(uuid())\n  name      String // Ej: \"Leche\", \"Huevos\"\n  quantity  Int      @default(1)\n  isBought  Boolean  @default(false) // Por defecto no está comprado\n  createdAt DateTime @default(now()) // Para ordenarlos por fecha\n\n  // Relación: Este producto pertenece a una Familia\n  familyId String\n  family   Family @relation(fields: [familyId], references: [id], onDelete: Cascade)\n}\n\nmodel Task {\n  id        String   @id @default(uuid())\n  name      String\n  isDone    Boolean  @default(false)\n  createdAt DateTime @default(now())\n\n  familyId String\n  family   Family @relation(fields: [familyId], references: [id], onDelete: Cascade)\n\n  @@map(\"tasks\")\n}\n\nmodel IdeaPlan {\n  id        String   @id @default(uuid())\n  name      String\n  isDone    Boolean  @default(false)\n  createdAt DateTime @default(now())\n\n  familyId String\n  family   Family @relation(fields: [familyId], references: [id], onDelete: Cascade)\n\n  @@map(\"ideas_plans\")\n}\n\nmodel Recipe {\n  id        String   @id @default(uuid())\n  name      String\n  createdAt DateTime @default(now())\n\n  familyId    String\n  family      Family             @relation(fields: [familyId], references: [id], onDelete: Cascade)\n  ingredients RecipeIngredient[]\n  steps       RecipeStep[]\n\n  @@map(\"recipes\")\n}\n\nmodel RecipeIngredient {\n  id        String     @id @default(uuid())\n  name      String\n  quantity  Float\n  unit      RecipeUnit\n  createdAt DateTime   @default(now())\n\n  recipeId String\n  recipe   Recipe @relation(fields: [recipeId], references: [id], onDelete: Cascade)\n\n  @@map(\"recipe_ingredients\")\n}\n\nmodel RecipeStep {\n  id          String @id @default(uuid())\n  description String\n  position    Int\n\n  recipeId String\n  recipe   Recipe @relation(fields: [recipeId], references: [id], onDelete: Cascade)\n\n  @@unique([recipeId, position])\n  @@map(\"recipe_steps\")\n}\n\nmodel MonthlyIncome {\n  id        String   @id @default(uuid())\n  month     String\n  amount    Float\n  createdAt DateTime @default(now())\n\n  userId   String\n  user     User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n  familyId String\n  family   Family @relation(fields: [familyId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, month])\n  @@index([familyId, month])\n  @@map(\"monthly_incomes\")\n}\n\nmodel ExpenseCategory {\n  id           String   @id @default(uuid())\n  name         String\n  emoji        String\n  monthlyLimit Float\n  createdAt    DateTime @default(now())\n\n  familyId String\n  family   Family    @relation(fields: [familyId], references: [id], onDelete: Cascade)\n  expenses Expense[]\n\n  @@map(\"expense_categories\")\n}\n\nmodel Expense {\n  id        String   @id @default(uuid())\n  month     String\n  name      String\n  emoji     String\n  amount    Float\n  createdAt DateTime @default(now())\n\n  familyId   String\n  family     Family           @relation(fields: [familyId], references: [id], onDelete: Cascade)\n  categoryId String?\n  category   ExpenseCategory? @relation(fields: [categoryId], references: [id], onDelete: SetNull)\n\n  @@index([familyId, month])\n  @@map(\"expenses\")\n}\n\nmodel CalendarEvent {\n  id          String   @id @default(uuid())\n  title       String // Nombre/Título del evento\n  description String? // Descripción opcional (ej: \"Llevar la comida\")\n  startAt     DateTime // Fecha y hora de inicio\n  endAt       DateTime // Fecha y hora de fin\n  isAllDay    Boolean  @default(false) // Si dura todo el día\n  color       String   @default(\"#3b82f6\") // Color en formato hex, por ejemplo azul de Tailwind\n  category    String? // Categoría opcional (ej: \"Médico\", \"Cumpleaños\", \"Escuela\", \"Ocio\")\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  // Relaciones\n  familyId  String\n  family    Family @relation(fields: [familyId], references: [id], onDelete: Cascade)\n  creatorId String\n  creator   User   @relation(fields: [creatorId], references: [id], onDelete: Cascade)\n\n  @@index([familyId])\n  @@index([startAt, endAt])\n  @@map(\"calendar_events\")\n}\n",
